import sys
from collections import deque

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        V = int(next(iterator))
    except StopIteration:
        return

    adj = [[] for _ in range(V)]

    for i in range(V):
        try:
            line_part = next(iterator)
            parts = line_part.split(',')
            neighbors = []
            for p in parts:
                if p.strip():
                    neighbors.append(int(p.strip()))
            adj[i] = neighbors
        except StopIteration:
            break

    in_degree = [0] * V
    rev_adj = [[] for _ in range(V)]

    for u in range(V):
        for v in adj[u]:
            rev_adj[v].append(u)
            in_degree[u] += 1

    queue = deque()
    for i in range(V):
        if in_degree[i] == 0:
            queue.append(i)

    safe = [False] * V

    while queue:
        node = queue.popleft()
        safe[node] = True
        for neighbor in rev_adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    result = [i for i in range(V) if safe[i]]
    result.sort()

    print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
